package com.nextfeet.nextfeet.repository; import java.util.*; import org.springframework.jdbc.core.*; import org.springframework.stereotype.Repository; import com.nextfeet.nextfeet.model.Usuario; @Repository public class UsuarioRepository implements UsuarioDAO { private final JdbcTemplate db; public UsuarioRepository(JdbcTemplate db){this.db=db;} private final RowMapper<Usuario> map=(r,n)->new Usuario(r.getInt("id"),r.getString("nombres"),r.getString("apellidos"),r.getString("correo"),r.getString("password"),r.getString("telefono"),r.getString("rol"),r.getString("estado")); public Usuario buscarPorCorreo(String c){return db.query("select * from usuario where correo=?",map,c).stream().findFirst().orElse(null);} public Usuario obtener(Integer id){return db.query("select * from usuario where id=?",map,id).stream().findFirst().orElse(null);} public List<Usuario> listar(String rol){return db.query("select * from usuario where rol=? order by id desc",map,rol);} public void crear(Usuario u){db.update("insert into usuario(nombres,apellidos,correo,password,telefono,rol,estado) values(?,?,?,?,?,?,?)",u.getNombres(),u.getApellidos(),u.getCorreo(),u.getPassword(),u.getTelefono(),u.getRol(),u.getEstado());} public void actualizar(Usuario u){db.update("update usuario set nombres=?,apellidos=?,correo=?,password=?,telefono=? where id=?",u.getNombres(),u.getApellidos(),u.getCorreo(),u.getPassword(),u.getTelefono(),u.getId());} public void cambiarEstado(Integer id,String e){db.update("update usuario set estado=? where id=?",e,id);} }